import { expect } from "chai";
import { network } from "hardhat";
import type { PlonkHarness } from "../types/ethers-contracts";
import { measure } from "./benchmark";
import { decodePlonkProof, encodePlonkProof, loadPlonkCase } from "./vectors";

const { ethers } = await network.create();

/** The largest gas limit of a transaction (EIP-7825). */
const MAX_TRANSACTION_GAS = 2n ** 24n;

// A PLONK proof of a lookup in a ternary Sparse Merkle Tree with 162-trit keys, generated by
// `tools/plonk-vectors`.
const lookup = loadPlonkCase(new URL("./vectors/", import.meta.url), "merkle");

describe("Merkle lookup benchmark", function () {
  let harness: PlonkHarness;

  before(async function () {
    harness = await ethers.deployContract("PlonkHarness");
  });

  it("decodes and encodes the proof like the Rust implementation", function () {
    expect(encodePlonkProof(decodePlonkProof(lookup.scpf, lookup.circuit))).to.equal(lookup.scpf);
  });

  it("verifies the proof against the circuit", async function () {
    const result = await harness.verify(lookup.circuit, lookup.scpf);
    const proof = decodePlonkProof(lookup.scpf, lookup.circuit);
    expect(result.publicInputs).to.deep.equal(proof.publicInputs);
    expect(result.options.grindingBits).to.equal(proof.options.grindingBits);
  });

  it("fits in the gas limit of a transaction", async function () {
    const result = await measure(ethers, harness, lookup);
    const proof = decodePlonkProof(lookup.scpf, lookup.circuit);
    const { foldRate, maxRounds, grindingBits } = proof.options;
    const applies = result.floorBinds ? ", which applies" : "";
    console.log(
      `      ${lookup.name}: fold rate ${foldRate}, max rounds ${maxRounds}, ` +
        `${grindingBits} grinding bits, ${proof.openings.length} queries\n` +
        `      proof size ${result.proofSize} bytes (calldata ${result.calldataSize} bytes)\n` +
        `      total gas ${result.totalGas}: calldata ${result.calldataGas} ` +
        `(EIP-7623 floor ${result.calldataFloorGas}${applies}), ` +
        `verification ${result.verificationGas}`,
    );
    expect(result.totalGas).to.be.lessThanOrEqual(MAX_TRANSACTION_GAS);
  });
});
